export function l2NormalizeVector(vec){let sum=0;const len=vec.length;for(let i=0;i<len;i++){sum+=vec[i]*vec[i]}const norm=Math.sqrt(sum)||1e-7;const invNorm=1/norm;for(let i=0;i<len;i++){vec[i]*=invNorm}return vec}export function dotProduct(a,b){const len=Math.min(a.length,b.length);let dot=0;for(let i=0;i<len;i++){dot+=a[i]*b[i]}return dot}export function extractDinov2Tokens(onnxOutput){const data=onnxOutput?.data||onnxOutput;const dims=Array.isArray(onnxOutput?.dims)?onnxOutput.dims:[];const dim=384;const numPatches=256;if(!data||data.length<dim){throw new Error(`DINOv2 ONNX tensor không hợp lệ: length=${data?.length}`)}const raw=data instanceof Float32Array?data:new Float32Array(data);if(raw.length>=257*dim||dims.length===3&&dims[1]===257&&dims[2]===dim){const clsToken=new Float32Array(dim);clsToken.set(raw.subarray(0,dim));l2NormalizeVector(clsToken);const patchTokens=new Float32Array(numPatches*dim);patchTokens.set(raw.subarray(dim,(numPatches+1)*dim));return{clsToken:clsToken,patchTokens:patchTokens,isSpatial:true}}if(raw.length===numPatches*dim){const patchTokens=new Float32Array(numPatches*dim);patchTokens.set(raw);const clsToken=new Float32Array(dim);for(let p=0;p<numPatches;p++){const offset=p*dim;for(let d=0;d<dim;d++){clsToken[d]+=patchTokens[offset+d]}}l2NormalizeVector(clsToken);return{clsToken:clsToken,patchTokens:patchTokens,isSpatial:true}}const clsToken=new Float32Array(dim);clsToken.set(raw.subarray(0,dim));l2NormalizeVector(clsToken);const patchTokens=new Float32Array(numPatches*dim);for(let p=0;p<numPatches;p++){patchTokens.set(clsToken,p*dim)}return{clsToken:clsToken,patchTokens:patchTokens,isSpatial:false}}export function downsampleTo16x16Grid(fgMask,scharrEdgeMap,size=224,gridDim=16){const mask16x16=new Float32Array(gridDim*gridDim);const edge16x16=new Float32Array(gridDim*gridDim);const cellSize=Math.floor(size/gridDim);const cellArea=cellSize*cellSize;for(let gr=0;gr<gridDim;gr++){const yStart=gr*cellSize;const yEnd=yStart+cellSize;for(let gc=0;gc<gridDim;gc++){const xStart=gc*cellSize;const xEnd=xStart+cellSize;const gridIdx=gr*gridDim+gc;let maskSum=0;let edgeSum=0;for(let y=yStart;y<yEnd;y++){const row=y*size;for(let x=xStart;x<xEnd;x++){const idx=row+x;if(fgMask[idx]===1){maskSum++;edgeSum+=scharrEdgeMap[idx]}}}mask16x16[gridIdx]=maskSum/cellArea;edge16x16[gridIdx]=maskSum>0?edgeSum/maskSum:0}}return{mask16x16:mask16x16,edge16x16:edge16x16}}export function computeHybridMaskedGemEmbedding(patchTokens,mask16x16,edge16x16){const dim=384;const numPatches=256;const pPower=3;const invP=1/pPower;let sumFgW=0;const fgWeights=new Float32Array(numPatches);for(let i=0;i<numPatches;i++){const m=mask16x16[i];if(m>=.15){fgWeights[i]=m;sumFgW+=m}}if(sumFgW<1e-4){for(let i=0;i<numPatches;i++){fgWeights[i]=1}sumFgW=numPatches}const gemVec=new Float32Array(dim);const invFgW=1/sumFgW;for(let d=0;d<dim;d++){let acc=0;for(let i=0;i<numPatches;i++){const w=fgWeights[i];if(w>0){const val=patchTokens[i*dim+d];const sign=Math.sign(val);const absVal=Math.max(Math.abs(val),1e-6);acc+=w*sign*Math.pow(absVal,pPower)}}const meanVal=acc*invFgW;gemVec[d]=Math.sign(meanVal)*Math.pow(Math.abs(meanVal),invP)}l2NormalizeVector(gemVec);let sumEdgeW=0;const edgeWeights=new Float32Array(numPatches);for(let i=0;i<numPatches;i++){const ew=mask16x16[i]*edge16x16[i];edgeWeights[i]=ew;sumEdgeW+=ew}if(sumEdgeW<1e-4){for(let i=0;i<numPatches;i++){edgeWeights[i]=fgWeights[i]}sumEdgeW=sumFgW}const detailVec=new Float32Array(dim);const invEdgeW=1/sumEdgeW;for(let d=0;d<dim;d++){let acc=0;for(let i=0;i<numPatches;i++){const ew=edgeWeights[i];if(ew>0){acc+=ew*patchTokens[i*dim+d]}}detailVec[d]=acc*invEdgeW}l2NormalizeVector(detailVec);const hybridVec=new Float32Array(768);for(let d=0;d<dim;d++){hybridVec[d]=.6*gemVec[d];hybridVec[dim+d]=.4*detailVec[d]}return l2NormalizeVector(hybridVec)}export function extractTopKeyPatches(patchTokens,mask16x16,edge16x16,topK=32){const dim=384;const numPatches=256;const candidates=[];for(let i=0;i<numPatches;i++){const w=mask16x16[i]*edge16x16[i];if(w>.05){candidates.push({gridIdx:i,weight:w})}}candidates.sort((a,b)=>b.weight-a.weight);const selected=candidates.slice(0,topK);const keyPatches=[];for(const item of selected){const vec=new Float32Array(dim);vec.set(patchTokens.subarray(item.gridIdx*dim,(item.gridIdx+1)*dim));l2NormalizeVector(vec);keyPatches.push({gridIdx:item.gridIdx,weight:Number(item.weight.toFixed(4)),vec:vec})}return keyPatches}export function executeGeometricGate(query,candidates){const total=candidates.length;const qAR=Math.max(.01,query.aspectRatio);const qSolidity=query.solidity;const qHoles=query.holeCount;const passedInitial=[];const scoredAll=[];for(const c of candidates){const cAR=Math.max(.01,c.aspectRatio);const arDiff=Math.abs(qAR-cAR)/Math.max(qAR,cAR);const solDiff=Math.abs(qSolidity-c.solidity);const holeDiff=Math.abs(qHoles-c.holeCount);const passesStrict=arDiff<=.22&&solDiff<=.12&&holeDiff<=1;if(passesStrict){passedInitial.push(c)}const geoDist=arDiff/.22+solDiff/.12+holeDiff/1;scoredAll.push({candidate:c,dist:geoDist})}if(passedInitial.length>=40||total<=40){return{passed:passedInitial,widened:false,diagnostics:{totalInput:total,initialPassedCount:passedInitial.length,finalCount:passedInitial.length}}}const passedWidened=[];for(const item of scoredAll){const c=item.candidate;const cAR=Math.max(.01,c.aspectRatio);const arDiff=Math.abs(qAR-cAR)/Math.max(qAR,cAR);const solDiff=Math.abs(qSolidity-c.solidity);const holeDiff=Math.abs(qHoles-c.holeCount);if(arDiff<=.33&&solDiff<=.18&&holeDiff<=2){passedWidened.push(c)}}scoredAll.sort((a,b)=>a.dist-b.dist);const top60=scoredAll.slice(0,60).map(s=>s.candidate);const finalPool=passedWidened.length>=40?passedWidened:top60;return{passed:finalPool,widened:true,diagnostics:{totalInput:total,initialPassedCount:passedInitial.length,finalCount:finalPool.length}}}export function synthesizePerspectiveCentroid(patchTokens,mask16x16,edge16x16){const canonicalEmbedding=computeHybridMaskedGemEmbedding(patchTokens,mask16x16,edge16x16);const m1=new Float32Array(256);for(let r=0;r<16;r++){for(let c=0;c<16;c++){const idx=r*16+c;const wCol=.7+.6*(c/15);m1[idx]=mask16x16[idx]*wCol}}const p1=computeHybridMaskedGemEmbedding(patchTokens,m1,edge16x16);const m2=new Float32Array(256);for(let r=0;r<16;r++){const wRow=.7+.6*(r/15);for(let c=0;c<16;c++){const idx=r*16+c;m2[idx]=mask16x16[idx]*wRow}}const p2=computeHybridMaskedGemEmbedding(patchTokens,m2,edge16x16);const e3=new Float32Array(256);for(let i=0;i<256;i++){e3[i]=Math.pow(edge16x16[i],.75)}const p3=computeHybridMaskedGemEmbedding(patchTokens,mask16x16,e3);const m4=new Float32Array(256);for(let i=0;i<256;i++){m4[i]=mask16x16[i]<.65?.35*mask16x16[i]:mask16x16[i]}const p4=computeHybridMaskedGemEmbedding(patchTokens,m4,edge16x16);const centroid=new Float32Array(768);for(let d=0;d<768;d++){centroid[d]=canonicalEmbedding[d]+p1[d]+p2[d]+p3[d]+p4[d]}return l2NormalizeVector(centroid)}export function rankStage2Candidates(queryHybridVec,candidates,topK=40){const scored=candidates.map(c=>{const canonicalScore=dotProduct(queryHybridVec,c.canonicalEmbedding);const perspectiveScore=dotProduct(queryHybridVec,c.perspectiveCentroid);const score=Math.max(canonicalScore,perspectiveScore);return{candidate:c,score:score,canonicalScore:canonicalScore,perspectiveScore:perspectiveScore}});scored.sort((a,b)=>b.score-a.score);return{top40:scored.slice(0,topK),queryHybridVec:queryHybridVec}}